  "sdm/seat_hold.py": "from dataclasses import dataclass\nfrom typing import Optional\n\n\n@dataclass\nclass Seat:\n    seat_id: str\n    state: str = \"available\"          # \"available\" | \"held\" | \"booked\"\n    holder: Optional[str] = None\n    hold_expires_at: float = 0.0\n\n    def hold(self, buyer: str, now: float, hold_seconds: float = 600) -> bool:\n        if self.state == \"held\" and now >= self.hold_expires_at:\n            self.state, self.holder = \"available\", None   # an expired hold frees the seat\n        if self.state != \"available\":\n            return False\n        self.state, self.holder = \"held\", buyer\n        self.hold_expires_at = now + hold_seconds\n        return True\n\n    def confirm(self, buyer: str, now: float) -> bool:\n        if self.state != \"held\" or self.holder != buyer or now >= self.hold_expires_at:\n            return False\n        self.state = \"booked\"\n        return True\n",
  "sdm/tiny_map.py": "def bucket_for(key: str, n_buckets: int) -> int:\n    \"\"\"A deliberately simple hash for teaching: add up character codes, wrap around the bucket count.\"\"\"\n    return sum(ord(c) for c in key) % n_buckets\n\n\nclass TinyMap:\n    \"\"\"A hash map built from a list of buckets; each bucket is a short list of (key, value) pairs.\"\"\"\n\n    def __init__(self, n_buckets: int = 8):\n        self.buckets = [[] for _ in range(n_buckets)]\n\n    def put(self, key: str, value) -> None:\n        bucket = self.buckets[bucket_for(key, len(self.buckets))]\n        for i, (k, _) in enumerate(bucket):\n            if k == key:\n                bucket[i] = (key, value)\n                return\n        bucket.append((key, value))\n\n    def get(self, key: str):\n        bucket = self.buckets[bucket_for(key, len(self.buckets))]\n        for k, v in bucket:\n            if k == key:\n                return v\n        return None\n",
